CREATE TABLE IF NOT EXISTS ledger_lock (id INTEGER PRIMARY KEY CHECK (id = 1), version BIGINT NOT NULL);
INSERT INTO ledger_lock (id, version) VALUES (1, 0) ON CONFLICT (id) DO NOTHING;
CREATE TABLE IF NOT EXISTS budget_lines (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payees (id TEXT PRIMARY KEY, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claims (id TEXT PRIMARY KEY, budget_line_id TEXT NOT NULL REFERENCES budget_lines(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals (id TEXT PRIMARY KEY, claim_id TEXT NOT NULL UNIQUE REFERENCES claims(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payouts (id TEXT PRIMARY KEY, claim_id TEXT NOT NULL UNIQUE REFERENCES claims(id), approval_id TEXT NOT NULL UNIQUE REFERENCES approvals(id), sender_batch_id TEXT NOT NULL UNIQUE, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payout_events (id TEXT PRIMARY KEY, payout_id TEXT NOT NULL REFERENCES payouts(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS receipt_sources (id TEXT PRIMARY KEY REFERENCES claims(id), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS submitted_requests (id TEXT PRIMARY KEY REFERENCES claims(id), payload TEXT NOT NULL);
